FUNCTION_BLOCK FB
VAR_INPUT
    enqueue: BOOL;
    dequeue: BOOL;
    reset: BOOL;
    capacity: DINT;
END_VAR
VAR_OUTPUT
    elementCount: DINT;
    status: WORD;
END_VAR
VAR_IN_OUT
    item: DINT;
    buffer: ARRAY[1..4] OF DINT;
END_VAR
VAR
    head: DINT := 1;
    tail: DINT := 1;
    enqueuePrev: BOOL := FALSE;
    dequeuePrev: BOOL := FALSE;
END_VAR

// Implementation
// At start of each call:
status := 16#0000; // No error default

IF reset THEN
    // Reset queue
    elementCount := 0;
    head := 1;
    tail := 1;
    // No need to clear buffer
ELSE
    // Detect rising edges
    VAR enqueueRising: BOOL;
    VAR dequeueRising: BOOL;
    enqueueRising := enqueue AND NOT enqueuePrev;
    dequeueRising := dequeue AND NOT dequeuePrev;

    // Process enqueue
    IF enqueueRising THEN
        IF elementCount < capacity THEN
            // Append item to tail
            buffer[tail] := item;
            elementCount := elementCount + 1;
            // Advance tail
            tail := (tail MOD capacity) + 1;
        ELSE
            // Queue full, reject
            status := 16#8002;
        END_IF
    END_IF

    // Process dequeue
    IF dequeueRising THEN
        IF elementCount > 0 THEN
            // Remove front element
            item := buffer[head];
            elementCount := elementCount - 1;
            // Advance head
            head := (head MOD capacity) + 1;
        ELSE
            // Queue empty, reject
            status := 16#8001;
        END_IF
    END_IF
END_IF

// Update previous signals for next cycle
enqueuePrev := enqueue;
dequeuePrev := dequeue;

END_FUNCTION_BLOCK

